/**
 * Lirune Reader Mobile — LiruneStorage config plugin
 *
 * `mobile/android/` is generated by `expo prebuild` and is git-ignored, so any
 * Kotlin source that only exists in the generated tree is destroyed by
 * `prebuild --clean`. This plugin makes the native `LiruneStorage` module part of
 * the repository:
 *
 *   1. the Kotlin sources are kept in `plugins/native/lirune-storage/` and copied
 *      into `android/app/src/main/java/com/lirune/reader/storage/` on every
 *      Android prebuild;
 *   2. `MainApplication.kt` — which prebuild regenerates — is patched to import
 *      and register `LiruneStoragePackage`.
 *
 * Both mods are idempotent: re-running prebuild over an already patched tree
 * changes nothing.
 */

const fs = require('fs');
const path = require('path');

const { withDangerousMod, withMainApplication, withAndroidManifest } = require('@expo/config-plugins');

const PACKAGE_CLASS = 'LiruneStoragePackage';
const PACKAGE_IMPORT = `com.lirune.reader.storage.${PACKAGE_CLASS}`;
const KOTLIN_SOURCE_DIR = path.join(__dirname, 'native', 'lirune-storage');

/** Absolute path of the generated Android package source directory. */
function androidKotlinDir(platformProjectRoot) {
  return path.join(platformProjectRoot, 'app', 'src', 'main', 'java', 'com', 'lirune', 'reader', 'storage');
}

function cleanManifestPermissions(manifest, isAllFiles = false) {
  const prohibited = new Set([
    'android.permission.MANAGE_DOCUMENTS',
    'android.permission.READ_MEDIA_IMAGES',
    'android.permission.READ_MEDIA_VIDEO',
    'android.permission.READ_MEDIA_AUDIO',
    'android.permission.WRITE_EXTERNAL_STORAGE',
  ]);
  if (!isAllFiles) {
    prohibited.add('android.permission.MANAGE_EXTERNAL_STORAGE');
  }

  const permissions = manifest['uses-permission'] || [];
  const filtered = permissions.filter((perm) => {
    const name = perm?.$?.['android:name'];
    return !prohibited.has(name);
  });

  const readExt = filtered.find(
    (perm) => perm?.$?.['android:name'] === 'android.permission.READ_EXTERNAL_STORAGE'
  );
  if (readExt) {
    if (!readExt.$) readExt.$ = { 'android:name': 'android.permission.READ_EXTERNAL_STORAGE' };
    readExt.$['android:maxSdkVersion'] = '32';
  } else {
    filtered.push({
      $: {
        'android:name': 'android.permission.READ_EXTERNAL_STORAGE',
        'android:maxSdkVersion': '32',
      },
    });
  }

  if (isAllFiles) {
    const hasManage = filtered.some(
      (perm) => perm?.$?.['android:name'] === 'android.permission.MANAGE_EXTERNAL_STORAGE'
    );
    if (!hasManage) {
      filtered.push({ $: { 'android:name': 'android.permission.MANAGE_EXTERNAL_STORAGE' } });
    }
  }

  manifest['uses-permission'] = filtered;
  return manifest;
}

const SUPPORTED_MIME_TYPES = [
  'application/epub+zip',
  'application/pdf',
  'text/plain',
  'text/html',
  'application/x-fictionbook+xml',
  'application/vnd.comicbook+zip',
  'application/x-cbz',
  'application/vnd.comicbook-rar',
  'application/x-cbr',
  'application/x-7z-compressed',
  'application/x-cb7',
  'application/x-mobipocket-ebook',
  'application/vnd.amazon.ebook',
  'application/x-mobi8-ebook',
  'image/vnd.djvu',
  'image/x-djvu',
  'application/msword',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/rtf',
  'text/rtf',
  'application/vnd.oasis.opendocument.text',
  'application/vnd.ms-htmlhelp',
  'application/x-chm',
  'application/zip',
  'application/x-zip-compressed',
  'application/x-zip',
];

const SUPPORTED_EXTENSIONS = [
  'epub',
  'pdf',
  'txt',
  'html',
  'htm',
  'xhtml',
  'fb2',
  'cbz',
  'cbr',
  'cb7',
  'mobi',
  'prc',
  'azw',
  'azw3',
  'kf8',
  'djvu',
  'djv',
  'doc',
  'docx',
  'rtf',
  'odt',
  'chm',
  'zip',
];

const BLOCKED_EXTENSIONS = [
  'apk',
  'jar',
  'aab',
  'xapk',
  'apks',
  'dex',
  'exe',
  'class',
  'arsc',
];

function buildExplicitIntentFilters() {
  const mimeData = [];
  for (const mime of SUPPORTED_MIME_TYPES) {
    mimeData.push({ $: { 'android:scheme': 'content', 'android:mimeType': mime } });
    mimeData.push({ $: { 'android:scheme': 'file', 'android:mimeType': mime } });
  }

  const mimeFilter = {
    action: [{ $: { 'android:name': 'android.intent.action.VIEW' } }],
    category: [
      { $: { 'android:name': 'android.intent.category.DEFAULT' } },
      { $: { 'android:name': 'android.intent.category.BROWSABLE' } },
    ],
    data: mimeData,
  };

  const extensionData = [];
  for (const ext of SUPPORTED_EXTENSIONS) {
    const variants = [ext.toLowerCase(), ext.toUpperCase()];
    for (const v of variants) {
      const patterns = [
        `.*\\.${v}`,
        `.*\\..*\\.${v}`,
        `.*\\..*\\..*\\.${v}`,
      ];
      for (const pattern of patterns) {
        extensionData.push({
          $: {
            'android:scheme': 'content',
            'android:host': '*',
            'android:pathPattern': pattern,
          },
        });
        extensionData.push({
          $: {
            'android:scheme': 'file',
            'android:host': '*',
            'android:pathPattern': pattern,
          },
        });
      }
    }
  }

  const extensionFilter = {
    action: [{ $: { 'android:name': 'android.intent.action.VIEW' } }],
    category: [
      { $: { 'android:name': 'android.intent.category.DEFAULT' } },
      { $: { 'android:name': 'android.intent.category.BROWSABLE' } },
    ],
    data: extensionData,
  };

  const sendData = SUPPORTED_MIME_TYPES.map((mime) => ({ $: { 'android:mimeType': mime } }));
  const sendFilter = {
    action: [{ $: { 'android:name': 'android.intent.action.SEND' } }],
    category: [{ $: { 'android:name': 'android.intent.category.DEFAULT' } }],
    data: sendData,
  };

  const sendMultipleFilter = {
    action: [{ $: { 'android:name': 'android.intent.action.SEND_MULTIPLE' } }],
    category: [{ $: { 'android:name': 'android.intent.category.DEFAULT' } }],
    data: sendData,
  };

  return [mimeFilter, extensionFilter, sendFilter, sendMultipleFilter];
}

function cleanAndConfigureIntentFilters(manifest) {
  const application = manifest.application?.[0];
  if (!application || !application.activity) return manifest;

  const mainActivity = application.activity.find((a) => a.$?.['android:name'] === '.MainActivity');
  if (!mainActivity) return manifest;

  const currentFilters = mainActivity['intent-filter'] || [];
  const preserved = currentFilters.filter((f) => {
    const actions = f.action || [];
    const isMain = actions.some((a) => a.$?.['android:name'] === 'android.intent.action.MAIN');
    const data = f.data || [];
    const isLiruneScheme = data.some((d) => d.$?.['android:scheme'] === 'lirune');
    return isMain || isLiruneScheme;
  });

  const explicitFilters = buildExplicitIntentFilters();
  mainActivity['intent-filter'] = [...preserved, ...explicitFilters];
  return manifest;
}

function withStorageManifest(config, options = {}) {
  const isAllFiles = Boolean(options.allFiles || process.env.LIRUNE_ALLFILES === '1');
  return withAndroidManifest(config, (cfg) => {
    if (cfg.modResults && cfg.modResults.manifest) {
      cfg.modResults.manifest = cleanManifestPermissions(cfg.modResults.manifest, isAllFiles);
      cfg.modResults.manifest = cleanAndConfigureIntentFilters(cfg.modResults.manifest);
    }
    return cfg;
  });
}

const RELEASE_MANIFEST_CONTENT = `<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android"
    xmlns:tools="http://schemas.android.com/tools">
    <uses-permission android:name="android.permission.INTERNET" tools:node="remove" />
</manifest>
`;

function writeReleaseManifestOverlay(platformProjectRoot) {
  const releaseDir = path.join(platformProjectRoot, 'app', 'src', 'release');
  fs.mkdirSync(releaseDir, { recursive: true });
  const manifestPath = path.join(releaseDir, 'AndroidManifest.xml');
  fs.writeFileSync(manifestPath, RELEASE_MANIFEST_CONTENT, 'utf8');
  return manifestPath;
}

function copyKotlinSources(config) {
  return withDangerousMod(config, [
    'android',
    (cfg) => {
      const { platformProjectRoot } = cfg.modRequest;
      if (!platformProjectRoot || !fs.existsSync(platformProjectRoot)) return cfg;

      const targetDir = androidKotlinDir(platformProjectRoot);
      fs.mkdirSync(targetDir, { recursive: true });

      for (const entry of fs.readdirSync(KOTLIN_SOURCE_DIR)) {
        if (!entry.endsWith('.kt')) continue;
        fs.copyFileSync(path.join(KOTLIN_SOURCE_DIR, entry), path.join(targetDir, entry));
      }

      writeReleaseManifestOverlay(platformProjectRoot);
      return cfg;
    },
  ]);
}

/**
 * Registers `LiruneStoragePackage` in a generated `MainApplication.kt`.
 *
 * Exported so the transformation can be asserted on directly — the real check for
 * this plugin is that it produces valid Kotlin for every template shape React
 * Native 0.7x-0.8x has shipped.
 */
function registerPackageInMainApplication(contents) {
  // Already patched (prebuild ran twice, or a previous plugin registered it).
  if (new RegExp(`add\\(\\s*${PACKAGE_CLASS}\\s*\\(\\s*\\)`).test(contents)) {
    return contents;
  }

  if (!contents.includes(`import ${PACKAGE_IMPORT}`)) {
    const importLine = `import ${PACKAGE_IMPORT}`;
    const firstImport = /(^|\n)(import\s+[^\n]+\n)/.exec(contents);
    contents = firstImport
      ? contents.replace(firstImport[0], `${firstImport[0]}${importLine}\n`)
      : `${importLine}\n${contents}`;
  }

  // React Native 0.7x-0.8x generate `PackageList(this).packages.apply { … }`;
  // a plain `PackageList(this).packages` is rewritten into that shape instead.
  if (/PackageList\(this\)\.packages\.apply\s*\{/.test(contents)) {
    return contents.replace(
      /PackageList\(this\)\.packages\.apply\s*\{\s*\n/,
      `PackageList(this).packages.apply {\n          add(${PACKAGE_CLASS}())\n`
    );
  }
  if (/PackageList\(this\)\.packages\b/.test(contents)) {
    return contents.replace(
      /PackageList\(this\)\.packages\b/,
      `PackageList(this).packages.apply {\n          add(${PACKAGE_CLASS}())\n        }`
    );
  }
  throw new Error(
    `withLiruneStorage: no PackageList(this).packages block found in MainApplication.kt; ` +
      'the generated template changed and this plugin needs updating.'
  );
}

function withPackageRegistration(config) {
  return withMainApplication(config, (cfg) => {
    cfg.modResults.contents = registerPackageInMainApplication(cfg.modResults.contents);
    return cfg;
  });
}

module.exports = function withLiruneStorage(config, options = {}) {
  return withStorageManifest(withPackageRegistration(copyKotlinSources(config)), options);
};

module.exports.registerPackageInMainApplication = registerPackageInMainApplication;
module.exports.cleanManifestPermissions = cleanManifestPermissions;
module.exports.cleanAndConfigureIntentFilters = cleanAndConfigureIntentFilters;
module.exports.SUPPORTED_MIME_TYPES = SUPPORTED_MIME_TYPES;
module.exports.SUPPORTED_EXTENSIONS = SUPPORTED_EXTENSIONS;
module.exports.BLOCKED_EXTENSIONS = BLOCKED_EXTENSIONS;
module.exports.writeReleaseManifestOverlay = writeReleaseManifestOverlay;
module.exports.RELEASE_MANIFEST_CONTENT = RELEASE_MANIFEST_CONTENT;